/// <summary>
///    The <c>UnitOfMeasureLookup</c> class provides the methods to perform lookup on the
///    <c>EcoResProduct</c> table, controls the <c>EcoResProductLookup</c> lookup form behavior, and
///    handles form events.
/// </summary>
class GUPCustDirectDebitMandateLookup
{
    public  boolean returnRefRecID = false;

}

Method.Source:
final public boolean parmreturnRefRecID(boolean _returnRefRecID = returnRefRecID)
{
    returnRefRecID = _returnRefRecID;

    return returnRefRecID;
}

public CustDirectDebitMandate performLookup(FormStringControl _formStringControl)
{
    Args args = new Args();
    args.name(formStr(GUPCustDirectDebitMandateLookup));
    args.caller(this);

    args.parmObject(this);
    args.lookupField(fieldNum(CustDirectDebitMandate, RecId));
    args.lookupValue(_formStringControl.valueStr());

    FormRun formRun = classfactory.formRunClass(args);
    formRun.init();

    _formStringControl.performFormLookup(formRun);
    CustDirectDebitMandate custDirectDebitMandate = formRun.selectRecordModeSelectedRecord() as CustDirectDebitMandate;

    return custDirectDebitMandate;
}

public static GUPCustDirectDebitMandateLookup construct(boolean _returnRefRecID)
{
    return new GUPCustDirectDebitMandateLookup(_returnRefRecID);
}
